package com.student.studentanalyzer.entity; import jakarta.persistence.*; @Entity @Table( name = "role_skill_requirements", uniqueConstraints = { @UniqueConstraint( columnNames = {"role_name", "skill_id"} ) } ) public class RoleSkillRequirement { @Id @GeneratedValue(strategy = GenerationType.IDENTITY) private Long id; @Column(name = "role_name", nullable = false) private String roleName; @ManyToOne(fetch = FetchType.EAGER) @JoinColumn(name = "skill_id", nullable = false) private Skill skill; @Column(nullable = false) private Integer requiredLevel; public RoleSkillRequirement() { } public Long getId() { return id; } public void setId(Long id) { this.id = id; } public String getRoleName() { return roleName; } public void setRoleName(String roleName) { this.roleName = roleName; } public Skill getSkill() { return skill; } public void setSkill(Skill skill) { this.skill = skill; } public Integer getRequiredLevel() { return requiredLevel; } public void setRequiredLevel(Integer requiredLevel) { this.requiredLevel = requiredLevel; } }